CREATE TABLE countries (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  iso2 TEXT UNIQUE NOT NULL,
  iso3 TEXT,
  phonecode TEXT,
  capital TEXT,
  currency TEXT,
  region TEXT,
  subregion TEXT,
  latitude TEXT,
  longitude TEXT,
  emoji TEXT
);
CREATE TABLE states (
  id INTEGER PRIMARY KEY,
  country_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  iso2 TEXT,
  latitude TEXT,
  longitude TEXT
);
CREATE TABLE cities (
  id INTEGER PRIMARY KEY,
  state_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  latitude TEXT,
  longitude TEXT
);
CREATE INDEX idx_states_country ON states(country_id);
CREATE INDEX idx_cities_state  ON cities(state_id);
CREATE INDEX idx_cities_name   ON cities(name);
